use super::*;
use semio_framework_value::{RetainedCloneGrant, RetainedCloneProgress, retirement::controlled::ControlledRetirement};
use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
use std::cell::Cell;

#[derive(Debug,PartialEq,semio_framework_value::RetireOwned)]
struct OriginalMutation(String);
impl protocol::OpBinary for OriginalMutation{
 fn encode_op(&self)->Result<Vec<u8>,protocol::ProtocolError>{Ok(self.0.as_bytes().to_vec())}
 fn decode_op(_: &[u8])->Result<Self,protocol::ProtocolError>{panic!("original receiving must never enter the whole operation decoder")}
}
#[derive(semio_framework_value::RetireOwned)]
struct OriginalMutationReceiving{field:Option<protocol::codec::RetainedWireFieldDecode>,text:Option<String>}
impl protocol::OpBinaryReceiving for OriginalMutation{
 type Receiving=OriginalMutationReceiving;
 fn admit_receiving(source:&[u8],range:(usize,usize),grant:RetainedCloneGrant)->Result<Option<(Self::Receiving,RetainedCloneProgress)>,ValueError>{if grant.maximum_items==0||grant.maximum_depth==0{return Ok(None)}Ok(Some((OriginalMutationReceiving{field:Some(protocol::codec::RetainedWireFieldDecode::new_range(source,range,true)?),text:None},RetainedCloneProgress{copied_items:1,..Default::default()})))}
}
impl protocol::OpBinaryReceivingCursor<OriginalMutation> for OriginalMutationReceiving{
 fn demands(&self,source:&[u8],copy:usize)->Result<semio_framework_value::RetirementDemand,ValueError>{self.field.as_ref().map_or(Ok(semio_framework_value::RetirementDemand{depth:1,..Default::default()}),|field|field.demands(source,copy))}
 fn step(&mut self,source:&[u8],native:&mut NativeDecodeControl<'_>,body:usize,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{let field=self.field.as_mut().unwrap();let result=if field.is_ready(){field.take_text_into(&mut self.text,grant)}else{native.charge(field.demands(source,body)?.capacity_bytes)?;field.advance(source,grant)};let progress=field.take_receipt().map_or(Default::default(),|(_,progress)|progress);result?;if field.terminal_is_empty(){self.field.take();}Ok(progress)}
 fn is_ready(&self)->bool{self.field.is_none()&&self.text.is_some()}
 fn take_into(&mut self,recipient:&mut Option<OriginalMutation>,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{if grant.maximum_items==0||grant.maximum_depth==0||recipient.is_some()||self.text.is_none(){return Ok(Default::default())}*recipient=self.text.take().map(OriginalMutation);Ok(RetainedCloneProgress{copied_items:1,..Default::default()})}
 fn close_demands(&self,_:usize)->Result<semio_framework_value::RetirementDemand,ValueError>{Ok(self.field.as_ref().map_or_else(||self.text.as_ref().map_or(Default::default(),|text|match text.chars().next_back(){Some(scalar)=>semio_framework_value::RetirementDemand{copy_bytes:scalar.len_utf8(),depth:1,..Default::default()},None=>semio_framework_value::RetirementDemand{release_bytes:text.capacity(),depth:1,..Default::default()}}),|field|field.retirement_demands()))}
 fn close_step(&mut self,grant:RetainedCloneGrant)->Result<semio_framework_value::RetainedCloneStep,ValueError>{if let Some(field)=self.field.as_mut(){field.cancel();field.close_step(grant)?;let progress=field.take_receipt().map_or(Default::default(),|(_,progress)|progress);if field.terminal_is_empty(){self.field.take();}return Ok(semio_framework_value::RetainedCloneStep::Progress(progress))}if let Some(text)=self.text.as_mut(){if grant.maximum_items==0||grant.maximum_depth==0{return Ok(semio_framework_value::RetainedCloneStep::Progress(Default::default()))}if let Some(scalar)=text.chars().next_back(){if grant.maximum_copy_bytes<scalar.len_utf8(){return Ok(semio_framework_value::RetainedCloneStep::Progress(Default::default()))}text.pop();return Ok(semio_framework_value::RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:scalar.len_utf8(),..Default::default()}))}let released_bytes=text.capacity();if grant.maximum_release_bytes<released_bytes{return Ok(semio_framework_value::RetainedCloneStep::Progress(Default::default()))}drop(self.text.take());return Ok(semio_framework_value::RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes,..Default::default()}))}Ok(semio_framework_value::RetainedCloneStep::Complete(Default::default()))}
 fn terminal_is_empty(&self)->bool{self.field.is_none()&&self.text.is_none()}
}
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn grant()->RetainedCloneGrant{serde_json::from_value(fixture()["turn"].clone()).unwrap()}
fn commands()->Vec<ArtifactCommand<OriginalMutation>>{
 let text="original command 源\0\r\n";let transaction=||TransactionRef{id:text.into(),tool:text.into()};let mutations=||vec![OriginalMutation(text.into()),OriginalMutation(text.repeat(2))];let inputs=||vec![SupersedeInput{target:MutationId(text.into()),replacement:Some(OriginalMutation(text.into()))},SupersedeInput{target:MutationId(text.into()),replacement:None}];
 let envelope=protocol::MutationEnvelope{mutation_id:MutationId(text.into()),document_id:protocol::ArtifactId(text.into()),actor:protocol::ActorId(text.into()),dependencies:vec![MutationId(text.into())],observed:Some(MutationId(text.into())),target:vec![text.into()],diff:protocol::ArtifactDiff{schema:protocol::SchemaId(text.into()),payload:vec![0,255,10]},inverse:protocol::InverseMutation{schema:protocol::SchemaId(text.into()),payload:vec![254,0,13]},timestamp:protocol::HybridLogicalTimestamp{actor:17,physical_ms:999,logical:9},transaction:Some(transaction()),verb:Some(text.into()),line:Some(text.into())};
 vec![ArtifactCommand::Apply{mutations:mutations(),transaction:Some(transaction())},ArtifactCommand::Undo,ArtifactCommand::Redo,ArtifactCommand::UndoWithPolicy{policy:protocol::UndoPolicy::SemanticUndo,semantic_command:Some(Box::new(ArtifactCommand::Apply{mutations:mutations(),transaction:Some(transaction())}))},ArtifactCommand::CommitCheckpoint{message:Some(text.into()),authors:vec![Author{id:text.into(),name:text.into(),avatar:None}]},ArtifactCommand::CreateAlternative{name:text.into()},ArtifactCommand::SwitchAlternative{alternative_id:text.into()},ArtifactCommand::CheckoutCheckpoint{checkpoint_id:text.into()},ArtifactCommand::IngestRemote{envelope},ArtifactCommand::PruneDrafts,ArtifactCommand::ApplyInLane{mutations:mutations(),lane:HistoryLane::Interaction,transaction:Some(transaction())},ArtifactCommand::UndoInLane{lane:HistoryLane::Interaction},ArtifactCommand::RedoInLane{lane:HistoryLane::Document},ArtifactCommand::SetMergePolicy{policy:protocol::MergePolicy::Vigilant},ArtifactCommand::ResolveConflict{conflict_id:text.into(),resolution:protocol::ConflictResolution::Accept},ArtifactCommand::Supersede{scope:Some(text.into()),inputs:inputs()},ArtifactCommand::CreateAlternativeWithSupersede{name:text.into(),inputs:inputs()},ArtifactCommand::AppendTransaction{mutations:mutations(),transaction:transaction()},ArtifactCommand::CommitTransaction{transaction_id:text.into()},ArtifactCommand::AbortTransaction{transaction_id:text.into()}]
}
fn observe<T>(run:impl FnOnce()->T)->(T,usize,usize){let(output,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(output,heap.requested_bytes,heap.released_bytes)}
fn close_cursor(mut cursor:RetainedArtifactCommandReceiving<OriginalMutation>,native:&mut NativeDecodeControl<'_>,grant:RetainedCloneGrant){for _ in 0..100000{if cursor.terminal_is_empty(){break}let demand=cursor.close_demands(grant.maximum_copy_bytes).unwrap();let(step,born,released)=observe(||{native.charge(demand.capacity_bytes).unwrap();cursor.close_step(grant).unwrap()});let progress=step.progress();assert!(progress.fits(grant));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));}assert!(cursor.terminal_is_empty());let((),born,released)=observe(||drop(cursor));assert_eq!((born,released),(0,0));}
fn close_output(output:ArtifactCommand<OriginalMutation>,native:&mut NativeDecodeControl<'_>,grant:RetainedCloneGrant){let mut owner=ControlledRetirement::new(output).unwrap_or_else(|_|unreachable!());for _ in 0..100000{if owner.terminal_is_empty(){break}let capacity=owner.next_capacity_byte_demand(grant.maximum_copy_bytes).unwrap();let(step,born,released)=observe(||{native.charge(capacity).unwrap();owner.step(grant).unwrap()});let progress=step.progress();assert!(progress.fits(grant));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));}assert!(owner.terminal_is_empty());let((),born,released)=observe(||drop(owner));assert_eq!((born,released),(0,0));}
#[test]
fn original_command_receiving_all_twenty_actual_variants_keep_nested_metadata_and_exact_physical_receipts(){
 let grant=grant();let maximum=fixture()["whole"]["maximumCapacityBytes"].as_u64().unwrap()as usize;
 for(command_index,command)in commands().into_iter().enumerate(){let source=command.encode_command().unwrap();let pointer=source.as_ptr();let mut callback=|_|true;let mut native=NativeDecodeControl::new(maximum,&mut callback);let(mut cursor,receipt)=RetainedArtifactCommandReceiving::<OriginalMutation>::admit(&source,(0,source.len()),grant).unwrap().unwrap();assert_eq!(receipt.copied_items,1);let mut output=None;let mut turns=0;
 for _ in 0..100000{let demand=cursor.demands(&source,grant.maximum_copy_bytes).unwrap();for axis in 0..5{let mut denied=grant;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4 if demand.depth>0=>denied.maximum_depth=demand.depth-1,_=>continue}let(progress,born,released)=observe(||cursor.step(&source,&mut native,grant.maximum_copy_bytes,denied).unwrap());assert_eq!(progress,Default::default());assert_eq!((born,released),(0,0));}
 let(progress,born,released)=observe(||if cursor.is_ready(){cursor.take_into(&mut output,grant).unwrap()}else{cursor.step(&source,&mut native,grant.maximum_copy_bytes,grant).unwrap()});assert!(progress.fits(grant));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));turns+=1;if output.is_some(){break}}
 assert_eq!(output.as_ref(),Some(&command));assert_eq!(source.as_ptr(),pointer);close_cursor(cursor,&mut native,grant);close_output(output.take().unwrap(),&mut native,grant);println!("[DEBUG] original command all20 index={command_index} turns={turns} sameSource={pointer:p} oneItem=true independentFiveAxes=true completeNestedMetadata=true physicalReceipt=true paidClose=true terminalDrop0");}
}
#[test]
fn original_command_receiving_every_interrupted_prefix_keeps_original_source_and_whole_native_failure(){
 let grant=grant();let maximum=fixture()["whole"]["maximumCapacityBytes"].as_u64().unwrap()as usize;
 for(command_index,command)in commands().into_iter().enumerate(){let source=command.encode_command().unwrap();let pointer=source.as_ptr();for cut in[0,1,2,7,17,64]{let enabled=Cell::new(true);let mut callback=|_|enabled.get();let mut native=NativeDecodeControl::new(maximum,&mut callback);let(mut cursor,_)=RetainedArtifactCommandReceiving::<OriginalMutation>::admit(&source,(0,source.len()),grant).unwrap().unwrap();let mut output=None;for _ in 0..cut{if cursor.is_ready(){break}let(progress,born,released)=observe(||cursor.step(&source,&mut native,grant.maximum_copy_bytes,grant).unwrap());assert!(progress.fits(grant));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));}
 if cursor.is_ready(){cursor.take_into(&mut output,grant).unwrap();}else{enabled.set(false);let(result,born,released)=observe(||cursor.step(&source,&mut native,grant.maximum_copy_bytes,grant));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!((born,released),(0,0));}enabled.set(true);close_cursor(cursor,&mut native,grant);if let Some(output)=output{close_output(output,&mut native,grant)}assert_eq!(source.as_ptr(),pointer);println!("[DEBUG] original command interrupted index={command_index} cut={cut} oneItem=true sameSource=true wholeNativeCause=true paidOriginalCursorClose=true terminalDrop0");}}
}
